import re


_VERSION_RE = re.compile(r"([0-9]+)\.([0-9]+)\.([0-9]+)\Z")
_HEADER_RE = re.compile(
    r"(?P<type>[a-z]+)(?:\((?P<scope>[^()]*)\))?(?P<breaking>!)?: (?P<text>\S.*)?\Z"
)


def next_version(current, commits):
    """The version after `current`, decided by the commit messages. See TASK.md."""
    match = _VERSION_RE.fullmatch(current) if isinstance(current, str) else None
    if match is None or any(part != "0" and part.startswith("0")
                            for part in match.groups()):
        raise ValueError("invalid version")

    major, minor, patch = (int(part) for part in match.groups())
    strongest = 0  # fix, feature, breaking are 1, 2, and 3 respectively.

    for message in commits:
        if not isinstance(message, str):
            continue
        lines = message.splitlines()
        if not lines:
            continue
        header = _HEADER_RE.fullmatch(lines[0])
        if header is None or header.group("scope") == "":
            continue

        change = 3 if header.group("breaking") else 0
        if header.group("type") == "feat":
            change = max(change, 2)
        elif header.group("type") == "fix":
            change = max(change, 1)
        if any(line.startswith("BREAKING CHANGE: ") or
               line.startswith("BREAKING-CHANGE: ") for line in lines[1:]):
            change = 3
        strongest = max(strongest, change)

    if strongest == 0:
        return current
    if strongest == 3:
        if major == 0:
            return f"0.{minor + 1}.0"
        return f"{major + 1}.0.0"
    if major == 0:
        return f"0.{minor}.{patch + 1}"
    if strongest == 2:
        return f"{major}.{minor + 1}.0"
    return f"{major}.{minor}.{patch + 1}"
